<?php
 namespace QQWorld\Cms\Model\Page\Source; use QQWorld\Framework\Data\OptionSourceInterface; use QQWorld\Framework\View\Model\PageLayout\Config\BuilderInterface; class PageLayout implements OptionSourceInterface { protected $pageLayoutBuilder; protected $options; public function __construct(BuilderInterface $pageLayoutBuilder) { $this->pageLayoutBuilder = $pageLayoutBuilder; } public function toOptionArray() { if ($this->options !== null) { return $this->options; } $configOptions = $this->pageLayoutBuilder->getPageLayoutsConfig()->getOptions(); $options = []; foreach ($configOptions as $key => $value) { $options[] = [ 'label' => $value, 'value' => $key, ]; } $this->options = $options; return $this->options; } } 